  "For those hours Home Assistant doesn't keep the house consumption, so we can't tell how much came from the sun. The band is right all the same.":
    "Para esas horas Home Assistant no guarda el consumo de la casa, así que no se sabe cuánto venía del sol. El tramo, en cambio, es el correcto.",
  "From the sun:": "Del sol:",
  "From these watts up the unit is on, below it is off. “My air conditioner draws 7 W while off”: with 20 written here, those 7 W stay off. Empty = the entity state decides, as before.":
    "A partir de estos vatios la unidad está encendida; por debajo, apagada. «Mi aire acondicionado consume 7 W estando apagado»: con 20 escrito aquí, esos 7 W siguen siendo apagado. Vacío = decide el estado de la entidad, como antes.",
