  "Split estimated from the house average": "Reparto estimado con la media de la casa",
  "Split measured hour by hour": "Reparto medido hora por hora",
  "Stop warning me about this": "No avisarme más de esto",
  "The band it draws most in:": "El tramo en el que más consume:",
  "The bin goes out the evening before. Pick the hour after which the pill stops announcing today's collection — by then already done — and announces tomorrow's instead. If nobody comes tomorrow, the pill does not show up.":
    "El cubo se saca la noche anterior. Elige la hora a partir de la cual la píldora deja de anunciar la recogida de hoy — ya pasada — y anuncia la de mañana. Si mañana no pasa nadie, la píldora no aparece.",
  "The camera panel is not there now. The alarm and the openings stay where they are, and the configured cameras have not been touched.":
    "Ahora el recuadro de las cámaras no está. La alarma y las aberturas siguen donde estaban, y las cámaras configuradas no se han tocado.",
  "The car service refused the integration's credentials: try again, and if it keeps happening reconnect the integration in Settings → Devices & services.":
    "El servicio del coche ha rechazado las credenciales de la integración: vuelve a intentarlo y, si sigue pasando, reconecta la integración en Ajustes → Dispositivos y servicios.",
  "The door and window contacts this panel watches: switch on the ones you want among the entry points. They show on the Security page under “Entry points”, with the same name and the same state they have under Openings.":
    "Los contactos de puertas y ventanas que vigila esta central: enciende los que quieras entre los accesos. Aparecen en la página Seguridad bajo «Accesos», con el mismo nombre y el mismo estado que tienen en Aperturas.",
  "The library cannot be read.": "No se puede leer la biblioteca.",
  "The numbers do not add up": "Las cuentas no cuadran",
  "The player did not answer.": "El reproductor no ha respondido.",
  "The presence sensors that belong to this panel: switch on the ones that are zones and leave the rest off. The Security page lists only the ones you switch on under “Zones”, and shows nothing at all while none is on.":
    "Los sensores de presencia que pertenecen a esta central: enciende los que son zonas y deja apagados los demás. La página Seguridad solo enumera bajo «Zonas» los que enciendas, y no muestra nada mientras no haya ninguno encendido.",
  "The radar above is a separate thing and works on its own.":
    "El radar de arriba es otra cosa y funciona por su cuenta.",
  "The sensors the appliance publishes that the fields above do not cover — air temperature and residual humidity of a dryer, a second door on a fridge: sensor.*, binary_sensor.*, number.* entities. They show up in the appliance window, with their own name and unit, in the order you add them.":
    "Los sensores que publica el aparato y que los campos de arriba no cubren — temperatura del aire y humedad residual de una secadora, una segunda puerta en un frigorífico: entidades sensor.*, binary_sensor.*, number.*. Aparecen en la ventana del aparato, con su nombre y su unidad, en el orden en que las añades.",
  "The top strip — hamburger, house name, weather — stays put while the rest of the dashboard scrolls under it. This device only.":
    "La franja superior — menú, nombre de la casa, tiempo — se queda fija mientras el resto del panel se desplaza por debajo. Solo en este dispositivo.",
  "The watt sensor of the plug the unit sits under. With the threshold below, it is the one that says whether the unit is running: an air conditioner driven by a plug knows it better than its own thermostat.":
    "El sensor en vatios del enchufe del que cuelga la unidad. Con el umbral de abajo es él quien dice si está funcionando: un aire acondicionado gobernado por un enchufe lo sabe mejor que su propio termostato.",
  "There are ${quante} configured cameras that are not shown here now.":
    "Hay ${quante} cámaras configuradas que ahora no se ven aquí.",
  "There is 1 configured camera that is not shown here now.":
    "Hay 1 cámara configurada que ahora no se ve aquí.",
  "There is no reading for this load right now.": "Ahora mismo no hay lectura para esta carga.",
  "They cost nothing at any hour, and the euros above are only on what it took from the grid.":
    "No cuestan nada a ninguna hora, y los euros de arriba son solo sobre lo que tomó de la red.",
  "They stay written here so you know they exist. The bell puts them back in the warning, if they are still silent.":
    "Se quedan escritos aquí para que sepas que existen. La campana los devuelve al aviso, si siguen mudos.",
  "This dashboard's configuration is reserved for its administrator.":
    "La configuración de este panel está reservada a su administrador.",
  "This entity is not present in this home.": "Esta entidad no existe en esta casa.",
  "This is an energy meter (kWh): it says how much it has consumed overall, not how much it is drawing right now. It is ignored here — it belongs in the “Total energy for history and Report” field.":
    "Esto es un contador de energía (kWh): dice cuánto ha consumido en total, no cuánto está consumiendo ahora. Aquí se ignora: va en el campo «Energía total para el historial y el informe».",
  "This sensor declares no unit of measurement: the card only shows W or kW sensors, and ignores this one.":
    "Este sensor no declara unidad de medida: la tarjeta solo muestra sensores en W o kW y este lo ignora.",
  "This sensor measures in “${misura}”: the card only shows W or kW sensors, and ignores this one.":
    "Este sensor mide en «${misura}»: la tarjeta solo muestra sensores en W o kW y este lo ignora.",
  "This weather entity has no forecast": "Esta entidad meteorológica no da el pronóstico",
  "To play": "Para reproducir",
  "Turn it off and the camera panel disappears from the Security page, leaving the alarm and the openings alone. The cameras stay configured: they come back by turning this on again.":
    "Apágalo y el recuadro de las cámaras desaparece de la página Seguridad, sin tocar la alarma ni las aberturas. Las cámaras siguen configuradas: vuelven volviendo a encender esto.",
  "Turn it off if this house has no panels: the Energy page stops showing production and self-sufficiency, and keeps consumption, costs and time bands. The entities written below stay where they are.":
    "Apágala si esta casa no tiene paneles: la página Energía deja de mostrar producción y autosuficiencia, y conserva consumo, costes y franjas horarias. Las entidades escritas debajo se quedan donde están.",
  "Vehicle kind": "Tipo de vehículo",
  Vehicles: "Vehículos",
  "Vertical swing": "Aletas verticales",
  "Water softener": "Descalcificador",
  "What lights the card up": "Qué enciende la tarjeta",
  "One tap picks it: while that entity is on, the appliance card and its Home tile take on a colour so you notice them. None is picked by default — a fridge opened to get the milk is not a fault — but the garage freezer door, or the washing machine finishing, belong here.":
    "Un toque lo elige: mientras esa entidad esté encendida, la tarjeta del electrodoméstico y su casilla en Inicio toman color para que las notes. De serie no hay ninguna elegida — una nevera abierta para coger la leche no es una avería — pero la puerta del congelador del garaje, o el fin de ciclo de la lavadora, van aquí.",
  "What to show in the window": "Qué mostrar en la ventana",
  "Where it is configured": "Dónde se configura",
  "Where we are": "Dónde estamos",
  "Which band it draws in": "En qué tramo consume",
  "Which rooms show up on Home, with the temperature and how many things are on: one tap takes you into the room. As many as you like; none ticked means no block at all.":
    "Qué habitaciones se ven en el inicio, con la temperatura y cuántas cosas están encendidas: un toque te lleva dentro de la habitación. Las que quieras; sin ninguna marcada no hay bloque.",
  "Windows and shutters": "Ventanas y persianas",
  "Zones and entry points of the panel": "Zonas y accesos de la central",
