  Error: "Error",
  "Estimated time": "Tiempo estimado",
  Events: "Eventos",
  "Every area is a Home Assistant panel of its own, with its own arming modes. The one marked “on the page now” is what the dial and the keypad are commanding: the eye beside another one brings it on screen in its place.":
    "Cada área es una central de Home Assistant con sus propios armados. La marcada «en pantalla ahora» es la que el cuadrante y el teclado están mandando: el ojo junto a otra la trae a pantalla en su lugar.",
  "Every field is optional: the card automatically shows what is available. Start, duration, energy and cost of the last cycle are computed automatically from power transitions unless you provide dedicated entities.":
    "Todos los campos son opcionales: la tarjeta muestra automáticamente lo que hay disponible. El inicio, la duración, la energía y el coste del último ciclo se calculan solos a partir de los cambios de potencia, salvo que indiques entidades específicas.",
  "Every filled box must be a cover.* or switch.* entity.":
    "Cada casilla rellenada debe ser una entidad cover.* o switch.*.",
  "Every load below is a circle of the Energy flow, under Home, in the order of this list. What you write here is what the flow shows, and the devices you file under it are the ones that appear when you tap the circle.":
    "Cada carga de abajo es un círculo del flujo de Energía, bajo Casa, en el orden de esta lista. Lo que escribas aquí es lo que muestra el flujo, y los dispositivos que archives en ella son los que aparecen al tocar el círculo.",
  "Every plant has its own meter, its own solar, its own battery and its own loads. The fields below belong to the selected plant: adding one starts from scratch and leaves what you already configured alone.":
    "Cada instalación tiene su contador, su fotovoltaica, su batería y sus cargas. Los campos de abajo son los de la instalación seleccionada: añadir una empieza de cero y no toca lo que ya has configurado.",
  "Every plant has its own thirteen fields. The one marked “on the page now” is what the Solar thermal page and the Home tile are showing: the eye beside another one brings it on screen in its place.":
    "Cada instalación tiene sus trece casillas. La marcada «en pantalla ahora» es lo que están mostrando la página Solar térmica y la tarjeta de Inicio: el ojo junto a otra la trae a pantalla en su lugar.",
  "Everything is here: the window's card shows its room's humidity and says to open as soon as it goes above the threshold.":
    "Está todo: la tarjeta de la ventana muestra la humedad de su habitación y dice de abrir en cuanto supera el umbral.",
  "Everything off": "Todo apagado",
  "Everything on the repository": "Todo lo que hay en el repositorio",
  "Everything the dashboard can do, and whether it shows. The same switch is also at the top of each section's own tab: here they are all together, so you can see what exists without opening them one by one.":
    "Todo lo que el panel sabe hacer, y si se ve. El mismo interruptor está también arriba en la pestaña de cada sección: aquí están todos juntos, para ver qué hay sin abrirlas una por una.",
