  Firefighter: "Bombero",
  "Fireplace pump": "Bomba de la chimenea",
  "First configure the circles connected to Home. Each circle can use a direct power sensor or automatically sum every child of a load group. Then create the appliances inside each group. Empty or disabled nodes are not forced into the flow.":
    "Configura primero los círculos conectados a Casa. Cada círculo puede usar un sensor de potencia directo o sumar automáticamente todas las cargas de su grupo. Después crea los electrodomésticos dentro de cada grupo. Los nodos vacíos o desactivados no se fuerzan en el flujo.",
  "First select your lights in the Lights step (or wizard).":
    "Primero elige tus luces en el paso Luces (o en el asistente).",
  Fixed: "Fija",
  "Fixed cycle duration (minutes)": "Duración fija del ciclo (minutos)",
  "Flap opened": "Tapa abierta",
  "Flightradar24 exposes “current in area”: the count, with the list of flights in the attributes.":
    "Flightradar24 expone «current in area»: el recuento, con la lista de vuelos en los atributos.",
  "Flights in the area": "Vuelos en la zona",
  "Flights overhead": "Vuelos sobre casa",
  "Flip the direction (ON = closed)": "Invertir el sentido (ON = cerrada)",
  "Flip the percentages (100 = closed)": "Invertir los porcentajes (100 = cerrada)",
  Flood: "Inundación",
  Floods: "Inundaciones",
  Floor: "Planta",
  "Floor (opt.)": "Planta (opc.)",
  "Floor icon": "Icono de la planta",
  Flow: "Ida",
  "Flow temperature": "Temperatura de ida",
  "Flow · Return · Pressure": "Ida · Retorno · Presión",
  "Flue extractor fan": "Extractor de humos",
  "Flue gas": "Humos",
  "Flue gas fan": "Ventilador de humos",
  "Flue gas temperature": "Temperatura de humos",
  "Followed train": "Tren seguido",
  Food: "Comida",
  "Food level": "Nivel de comida",
  "Food running low": "Se está acabando la comida",
  "For each item enter": "Para cada elemento escribe",
  "For every source, Total energy meter is the cumulative Recorder source (normally state_class: total_increasing). It is not a period value: day, month and year are calculated as final Recorder sum minus initial Recorder sum, so meter resets are preserved. Period sensors are optional current-period overrides.":
    "Para cada fuente, el contador de energía total es la fuente acumulada de Recorder (normalmente state_class: total_increasing). No es un valor de periodo: el día, el mes y el año se calculan como suma final de Recorder menos suma inicial, de modo que se respetan los reinicios del contador. Los sensores de periodo son sustituciones opcionales del periodo actual.",
  "For fridge and freezer: shows the temperature strip instead of the power bar.":
    "Para frigorífico y congelador: muestra la franja de temperatura en vez de la barra de potencia.",
  "For lights you only want to see, with no accidental taps: the row stays where it is, the button stops responding.":
    "Para luces que solo quieres ver, sin toques accidentales: la fila se queda donde está, el botón deja de responder.",
  "For sockets that must not be switched off: the fridge, the modem, the freezer. The row stays where it is, the button stops responding.":
    "Para los enchufes que no deben apagarse: la nevera, el módem, el congelador. La fila se queda donde está, el botón deja de responder.",
  "For this window only: resting at this percentage or below counts as closed. Empty, the house threshold at the top applies.":
    "Solo para esta ventana: parada en este porcentaje o por debajo cuenta como cerrada. Vacío, vale el umbral de la casa de arriba.",
  "For this window only: when its room's humidity goes above this level, the card says to open it to air out. Empty, the house threshold at the top applies; zero turns the advice off on this window.":
    "Solo para esta ventana: cuando la humedad de su habitación supera esta cuota, la tarjeta dice de abrirla para ventilar. Vacía, vale el umbral de la casa escrito arriba; cero apaga el consejo en esta ventana.",
  "For those without a panel: an alarm built with ESPHome, with scripts or with a list of modes. Each button below shows up in the Security section and on the Home tile, next to the panel's own — and when there is no panel, in their place.":
    "Para quien no tiene central: una alarma hecha con ESPHome, con scripts o con una lista de modos. Cada botón de aquí aparece en la sección Seguridad y en la tarjeta de Inicio, junto a los de la central — y si no hay central, en su lugar.",
  "For what recharges instead of being replaced: the wall tablet, a power bank. The two entities are number.* or input_number.*, the ones the device exposes to say where it starts again and where it stops. Leave them empty and this stays a battery like the others.":
    "Para lo que se recarga en vez de cambiarse: la tableta de pared, una batería externa. Las dos entidades son number.* o input_number.*, las que el dispositivo expone para decir dónde vuelve a empezar y dónde se detiene. Déjalas vacías y esta seguirá siendo una pila como las demás.",
  "Force (ignore rain)": "Forzar (ignorar lluvia)",
  Forest: "Bosque",
  "Found next to the appliance — one tap adds them:":
    "Encontrados junto al electrodoméstico: un toque los añade:",
  "Found next to the player — one tap adds them:":
    "Encontrados junto al reproductor — un toque los añade:",
  "Found next to the robot — one tap adds them:": "Encontrados junto al robot: un toque los añade:",
  "Fountain filter": "Filtro de la fuente",
  "Four sensors of your choosing: the ones you actually read to decide, not a house average. The typical one is outdoors, the one you go by for the indoor units. The unit comes from Home Assistant, and a sensor you do not name is a pill that does not show up.":
    "Cuatro sensores elegidos por ti: los que lees de verdad para decidir, no una media de la casa. El típico es el de fuera, con el que te guías para los climas de dentro. La unidad la dice Home Assistant, y un sensor que no indicas es una pastilla que no aparece.",
