  Good: "Buena",
  "Good up to the first, fair up to the second, poor up to the third, bad beyond. The defaults are the norms: the European index bands for particulates and gases, EN 16798-1 for CO₂, the WHO guidelines for monoxide. Change them only if you know why.":
    "Buena hasta el primero, aceptable hasta el segundo, mala hasta el tercero, muy mala más allá. De serie son las normas: las bandas del índice europeo para partículas y gases, la EN 16798-1 para el CO₂, las guías de la OMS para el monóxido. Cámbialas solo si sabes por qué.",
