  "Instead of a path you can write an image entity (image.car) or a camera (camera.car): the integration keeps the photo up to date, and the 🔍 lens finds it for you.":
    "En lugar de una ruta puedes escribir una entidad de imagen (image.coche) o una cámara (camera.coche): la integración mantiene la foto al día, y la lupa 🔍 te la busca.",
  "Instead of sitting in the “Highlights” summary, this entity gets its own tile on Home, which opens on it when tapped.":
    "En lugar de estar en el resumen «Destacados», esta entidad tiene su propia tarjeta en Inicio, que al tocarla se abre sobre ella.",
