  "Leave empty if you prefer": "Déjalo vacío si lo prefieres",
  "Leave it as the group icon to follow it; change it to tell this opening from the others.":
    "Déjalo igual al icono del grupo para seguirlo; cámbialo para distinguir esta abertura de las demás.",
  "Leave it empty and the circle is the total of the appliances below. Fill it in only if a clamp meter covers the whole line.":
    "Déjalo vacío y el círculo será el total de los electrodomésticos de abajo. Rellénalo solo si una pinza amperimétrica cubre toda la línea.",
  "Leave it empty and the worst reading goes on the cover, which is the right answer when nothing is said. If your station already publishes its own index, put it here: the big number becomes its own, and the substances are read one by one by opening the card. The verdict still belongs to the worst reading — an index saying “good” must not hide a particulate saying “bad”.":
    "Déjalo vacío y en portada va la medida peor, que es la respuesta correcta cuando no se dice nada. Si tu estación ya publica su propio índice, ponlo aquí: el número grande pasa a ser el suyo, y las sustancias se leen una a una abriendo la tarjeta. El veredicto sigue siendo de la medida peor: un índice que dice «buena» no debe tapar unas partículas que dicen «mala».",
  "Leave it empty for something with no due date. With a date it shows up in the agenda, on its day.":
    "Déjalo vacío para algo sin fecha. Con una fecha aparece en la agenda, en su día.",
  "Left on the Home Assistant language the dashboard follows the profile of whoever is looking. Picking one pins it for this dashboard, even when Home Assistant speaks another language.":
    "Dejándolo en el idioma de Home Assistant el panel sigue el perfil de quien está mirando. Elegir uno lo fija para este panel, aunque Home Assistant hable otro idioma.",
