  Off: "Apagado",
  "Off / Closed (off)": "Apagado / Cerrado (off)",
  "Off, the weather entity above is enough: temperature, humidity and wind come from it.":
    "Apagado, basta la entidad weather de arriba: temperatura, humedad y viento se leen de ella.",
  Office: "Despacho",
  Official: "Oficial",
  Oil: "Aceite",
  "Oil temperature": "Temperatura del aceite",
  "Old man": "Anciano",
  "Old woman": "Anciana",
  On: "Encendido",
  "On / Active / Open (on)": "Encendido / Activo / Abierto (on)",
  "On Home": "En Inicio",
  "On battery": "En batería",
  "On battery · ${carica}%": "En batería · ${carica} %",
  "On cards show the room temperature big (target below)":
    "En las tarjetas muestra grande la temperatura ambiente (objetivo debajo)",
  "On mains": "En red",
  "On time": "En hora",
  "On which page": "En qué página",
  "On, the radar plays the last hour of rain: you see which way the front is moving, not only where it is now. That is six frames instead of one, so six rounds of tiles: turn it off on a slow connection, or if you prefer a single image.":
    "Activado, el radar muestra en movimiento la última hora de lluvia: se ve hacia dónde va el frente, no solo dónde está ahora. Son seis fotogramas en vez de uno, o sea seis rondas de teselas: desactívalo si la conexión es lenta o si prefieres una sola imagen.",
  "On/off control": "Mando de encendido/apagado",
  "On/off · Brightness · Colour": "Encendido/apagado · Brillo · Color",
  "On/off · Consumption · Room by room": "Encendido/apagado · Consumo · Habitación por habitación",
  "One bin per material, and for each the sensor that says when the collection comes: the page answers the evening question — what do I put out tonight — and the Home tile lights up the day before. Whoever has a single calendar, with one event per collection, puts it in the box at the bottom.":
    "Un cubo por material, y para cada uno el sensor que dice cuándo llega la recogida: la página responde a la pregunta de la noche — qué saco esta noche — y la tarjeta de Inicio se enciende el día antes. Quien tiene un solo calendario, con un evento por recogida, lo pone en la casilla de abajo.",
  "One room at a time · Scenes · Sensors": "Una habitación a la vez · Escenas · Sensores",
  "One single tile": "Una sola tarjeta",
  "One step, and you will never be asked again: open github.com/login/device and type this code.":
    "Un solo paso, y no te lo pedirá nunca más: abre github.com/login/device y escribe este código.",
  "One tile per plant": "Una por instalación",
  "One window can carry all three: fill in the boxes you have, the box tells the type.":
    "En una ventana pueden estar las tres: rellena las casillas que tengas, la casilla ya dice el tipo.",
  "Only daily sensors or Recorder deltas from cumulative total meters are counted. Lifetime values are never added directly.":
    "Solo se cuentan los sensores diarios o los incrementos de Recorder de los contadores totales acumulados. Los valores acumulados nunca se suman directamente.",
  "Only if you already have a helper measuring the period. Without one, the period comes from the total meter.":
    "Solo si ya tienes un helper que mida el periodo. Sin él, el periodo sale del contador total.",
  "Only needed when the shutter is driven by two relays — one that sends it up, one that sends it down — like a Shelly left in switch mode: then “Close” switches this one on, and “Stop” switches both off. With a real cover.* leave it empty.":
    "Solo hace falta cuando la persiana la mueven dos relés — uno que la sube y otro que la baja — como un Shelly dejado en modo interruptor: entonces «Cerrar» enciende este y «Parar» apaga los dos. Con una cover.* de verdad, déjalo vacío.",
  "Only rooms containing a light are shown. Edit opens all light fields, not a browser prompt. The pills say what each light can do — RGB, tunable white, dimmer or plain on/off — and that is what drives the controls in the popup.":
    "Solo se muestran las estancias que contienen una luz. Editar abre todos los campos de la luz, no un aviso del navegador. Las etiquetas indican qué puede hacer cada luz —RGB, blanco ajustable, regulador o simple encendido/apagado— y eso es lo que decide los mandos de la ventana.",
  "Only the modes the panel actually accepts are listed. Removing one hides it from the section and changes nothing about what the panel can do; disarm always stays.":
    "Solo aparecen los modos que la central acepta de verdad. Quitar uno lo oculta de la sección y no cambia nada de lo que la central sabe hacer; desarmar se queda siempre.",
  "Only with the soil below (%)": "Solo con el suelo por debajo (%)",
  Open: "Abierta",
  "Open (as before)": "Abrir (como antes)",
  "Open the menu": "Abrir el menú",
  "⚪ Empty section — add an entity below to show it":
    "⚪ Sección vacía — añade una entidad abajo para mostrarla",
  "You haven't saved": "No has guardado",
  "You entered entities in this section without saving them. If you leave now, they will be lost.":
    "Has introducido entidades en esta sección sin guardarlas. Si sales ahora, se perderán.",
  "Save and continue": "Guardar y continuar",
  "Leave without saving": "Salir sin guardar",
  "Stay here": "Quedarse aquí",
  "Nobody home": "No hay nadie en casa",
  "Big buttons: a dashboard action or any entity (a scene, a script, a button). For each one the name on the tablet, the line below and the drawing.":
    "Botones grandes: una acción del panel o cualquier entidad (una escena, un script, un botón). Para cada uno, el nombre en la tableta, la línea de abajo y el dibujo.",
  "Full config": "Configuración completa",
  "On, a light added to the room in the source dashboard shows up by itself. Off, the slots are chosen here: any entity or action, with the name and drawing you want.":
    "Activado, una luz añadida a la habitación en el panel de origen aparece sola. Desactivado, los espacios se eligen aquí: cualquier entidad o acción, con el nombre y el dibujo que quieras.",
  "Slots of your own: in each one any Home Assistant entity — a light, a socket, a lock, a sensor — or a dashboard action, with the name and drawing you want.":
    "Espacios totalmente tuyos: en cada uno cualquier entidad de Home Assistant —una luz, un enchufe, una cerradura, un sensor— o una acción del panel, con el nombre y el dibujo que quieras.",
  "A dehumidifier is not a thermostat: pick its humidifier entity and the Climate page gives it a card of its own, with the current humidity, the target, the modes, the fan and the tank-full warning. The other fields fill themselves in when you save.":
    "Un deshumidificador no es un termostato: elige su entidad humidifier y la página de Clima le da una tarjeta propia, con la humedad actual, el objetivo, los modos, el ventilador y el aviso de depósito lleno. Los demás campos se rellenan solos al guardar.",
  "Add a dehumidifier": "Añadir un deshumidificador",
  "Alongside (filled in automatically on save)": "Al lado (se rellenan solos al guardar)",
