  Shutters: "Persianas",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "Las persianas y las cortinas aparecen en la página 🪟 Ventanas, agrupadas por planta y habitación. Cada fila acepta una entidad cover.* — con posición y porcentajes — o un relé switch.*: uno solo si al encenderlo la persiana se queda arriba, dos si uno sube y otro baja, como un Shelly en modo interruptor. Si la ventana se abre a mano — contraventanas, postigos, una manilla —, deja vacías las casillas de mando y rellena solo el sensor de apertura: la tarjeta se dibuja igual y dice si está abierta.",
  "Shutters · Curtains · Contact sensors": "Persianas · Cortinas · Sensores de apertura",
  "Sign path timeout": "Tiempo agotado al firmar la ruta",
  "Simple alternative to the duration entity.": "Alternativa sencilla a la entidad de duración.",
  "Since last charge": "Desde la última carga",
  "Since last restart": "Desde el último reinicio",
  Singer: "Cantante",
  "Single calendar or sensor (optional)": "Calendario o sensor único (opcional)",
  "Skin tone": "Tono de piel",
  "Skip detection →": "Saltar la detección →",
  "Skip the program if ≥ (%)": "Omitir el programa si ≥ (%)",
