  "Slightly warm": "Ligeramente cálido",
  "Small pool": "Piscina pequeña",
  "Smart thermostats publish the heating mode on a separate entity: TADO has Home and Away, others add Holiday or Boost. The card shows it, and if the entity is a select or an input_select you can change it right there.":
    "Los termostatos inteligentes publican el modo de calefacción en una entidad aparte: TADO tiene En casa y Fuera, otros añaden Vacaciones o Boost. La tarjeta lo muestra, y si la entidad es un select o un input_select puedes cambiarlo ahí mismo.",
  "SmartThings, Sonos, Chromecast, AirPlay… pick the device and the player arrives ready-made: its entity, the controls the integration publishes next to it — a TV's power switch, the input dropdown — and its readings. Or, below, one field at a time.":
    "SmartThings, Sonos, Chromecast, AirPlay… elige el dispositivo y el reproductor llega hecho: su entidad, los mandos que la integración publica al lado — el interruptor de una tele, el desplegable de la fuente — y sus lecturas. O, aquí abajo, casilla a casilla.",
