  "Turn everything on": "Encender todo",
  "Turn it off to open on the first tap: whoever opens their own front door ten times a day knows the confirmation by heart. A PIN is not a confirmation and stays: a protected door keeps asking for it.":
    "Apágala para abrir al primer toque: quien abre su propio portón diez veces al día se sabe la confirmación de memoria. El PIN no es una confirmación y se queda: una puerta protegida lo sigue pidiendo.",
  "Turn off": "Apagar",
  "Turn on": "Encender",
  "Turn on or off": "Encender o apagar",
  "Turn on/off": "Encender/apagar",
  "Turn the boiler on or off": "Encender o apagar la caldera",
  "Turning them on and off": "Encender y apagar",
  Tuxedo: "Esmoquin",
  "Two shots of the same car: the dashboard shows the plugged-in one while it charges and the other one the rest of the time. The first is enough — without the second it simply stays.":
    "Dos fotos del mismo coche: el panel muestra la del coche enchufado mientras carga y la otra el resto del tiempo. Con la primera basta; sin la segunda simplemente se queda.",
  "Two weeks that repeat, written by hand: tap a day and pick what goes out. No sensor and no Home Assistant calendar needed — the page and the Home tile read this exactly as they would read an integration. A material that already has its own sensor above is not repeated: the sensor wins.":
    "Dos semanas que se repiten, escritas a mano: toca un día y elige qué sale. No hace falta ningún sensor ni ningún calendario de Home Assistant — la página y la tarjeta de Inicio leen esto igual que leerían una integración. Un material que ya tiene su sensor arriba no se repite: manda el sensor.",
  Type: "Tipo",
  "Type / artwork": "Tipo / ilustración",
  "Type at least two letters: it searches every tab at once.":
    "Escribe al menos dos letras: busca en todas las pestañas a la vez.",
  "Type the code…": "Escribe el código…",
  "Type your question…": "Escribe tu pregunta…",
  "Tyre pressure": "Presión de los neumáticos",
  Tyres: "Neumáticos",
  "Tyres fine": "Neumáticos bien",
