  What: "Qué",
  "What goes out this day": "Qué sale este día",
  "What is in the boiler room": "Qué hay en el cuarto de calderas",
  "What it can do": "Qué puede hacer",
  "What it shows": "Qué muestra",
  "What the Instant view shows.": "Lo que muestra la vista Instantáneo.",
  "What the tap does": "Qué hace el toque",
  "What this unit's button does in the Home climate popup. Empty = leave alone.":
    "Qué hace el botón de esta unidad en el popup Clima de Inicio. Vacío = no tocar.",
  "What to press": "Qué pulsar",
  "What trips, and for what: person, animal, vehicle, motion. When one of them turns on, the Cameras tile on the Home says so — with the camera name and the time — and the frame is right there. The boxes are prefilled with the sensors sitting next to each camera: correct them if it got it wrong, empty them to stop watching.":
    "Qué salta, y por qué: persona, animal, vehículo, movimiento. Cuando uno de ellos se enciende, la tarjeta Cámaras de la Home lo dice —con el nombre de la cámara y la hora— y el fotograma está ahí dentro. Las casillas vienen rellenas con los sensores que hay junto a cada cámara: corrígelas si se ha equivocado, vacíalas para dejar de mirarlas.",
  "What you are trying to achieve and where you got stuck.":
    "Qué quieres conseguir y dónde te has quedado atascado.",
  "What you did, what you expected, what happened instead.":
    "Qué hiciste, qué esperabas y qué ocurrió en su lugar.",
  "What you would need it for, and how you picture it in the dashboard.":
    "Para qué te serviría y cómo te la imaginas en el panel.",
  "What you write here reaches whoever maintains the dashboard, and nobody else. It does not go through GitHub and does not become public. Along with the message only the dashboard version, the Home Assistant version and the language are sent. You can delete the conversation whenever you want.":
    "Lo que escribas aquí llega a quien mantiene el panel, y a nadie más. No pasa por GitHub y no se hace público. Junto al mensaje solo se envían la versión del panel, la de Home Assistant y el idioma. Puedes eliminar la conversación cuando quieras.",
  When: "Cuándo",
  "When Solar and Grid are configured, Home consumption uses the same flow balance as Home Assistant. The total kWh meter wins: when one is set, day, month and year are derived from it through Recorder and the period fields are not read. The daily, monthly and annual fields are for when no total meter exists.":
    "Cuando Solar y Red están configurados, el consumo de Casa usa el mismo balance de flujo que Home Assistant. Manda el contador total de kWh: si hay uno, el día, el mes y el año se derivan de él a través de Recorder y los campos de periodo no se leen. Los campos diario, mensual y anual son para cuando no existe contador total.",
  "When a custom alert turns on, the dashboard opens it by itself. Only when it turns on, and never on top of a window that is already open.":
    "Cuando un aviso personalizado se enciende, el panel lo abre solo. Solo al encenderse, y nunca encima de una ventana ya abierta.",
  "When a room's humidity goes above this level, that room's window suggests opening it to air out. The humidity is the room sensor's. It applies to the windows without a threshold of their own in their row. Empty means 60. Zero turns the suggestion off.":
    "Cuando la humedad de una habitación supera esta cuota, la ventana de esa habitación sugiere abrirla para ventilar. La humedad es la del sensor de la habitación. Vale para las ventanas que no tienen un umbral propio en su fila. Vacío vale 60. Cero apaga la sugerencia.",
  "When set, the button opens the keypad and only fires with the right code — the same keypad as the panel. Empty, it fires on tap.":
    "Si lo escribes, el botón abre el teclado y solo actúa con el código correcto — el mismo teclado de la central. Vacío, actúa al tocarlo.",
  "When the litter box was last cleaned: a date, or the minutes gone by. Past the hours set below the card says so.":
    "Cuándo se limpió el arenero por última vez: una fecha, o los minutos transcurridos. Pasadas las horas indicadas abajo, la tarjeta lo dice.",
  Where: "Dónde",
  "Where it is raining now": "Dónde está lloviendo ahora",
  "Where the heat is going is told by how it sits: to the heating or to the hot water.":
    "Por cómo está se ve adónde va el calor: a la calefacción o al agua caliente.",
  "Where to read if it is armed": "Dónde se lee si está armado",
  "Which entity the dashboard uses": "Qué entidad usa el panel",
  "Which integrations": "Qué integraciones",
  "Which material": "Qué material",
  "Which option": "Qué opción de la lista",
  "Which sections are visible": "Qué secciones se ven",
  Whiskers: "Michi",
  White: "Blanco",
  "Who is at the door and what is in the mailbox. The intercom needs the button that opens — a button, a script, a lock, a motorised gate — and the doorbell if there is one. One sensor is enough for the mailbox: with both — the one that says something arrived and the flap one — the dashboard compares the two moments and works out on its own whether the mail is still inside; with only one, an opening counts as an arrival, and you are the one who says you took it, with the button on the card.":
    "Quién está en la puerta y qué hay en el buzón. Del portero hacen falta el botón que abre —un button, un script, una cerradura, una cancela motorizada— y el timbre, si lo hay. Del buzón hacen falta el sensor que dice que ha llegado algo y el que dice que se ha abierto la tapa: del cotejo de los dos momentos el panel sabe si el correo sigue dentro. También basta un solo sensor: con uno solo, una apertura cuenta como llegada, y eres tú quien dice que la has recogido, con el botón de la tarjeta.",
  "Who is watching?": "¿Quién está mirando?",
  "Who rings · Open · Mailbox": "Quién llama · Abrir · Buzón",
  "Who this is, by their home name": "Quién es, con su nombre de casa",
  "Whole house": "Toda la casa",
  "Whose it is": "De quién es",
