  "Windows open": "Ventanillas abiertas",
  Winter: "Invierno",
  "With Auto they shrink on narrow screens only": "Con Auto se encogen solo en pantallas estrechas",
  "With a photo the avatar is not shown: the photo wins.":
    "Con una foto el avatar no se ve: la foto gana.",
  "With a total meter configured the dashboard derives day, month and year from it through Recorder, so the numbers agree with each other. Entities written in the period fields stay saved but are not used: clear them, or remove the total meter if you would rather read the periods directly.":
    "Con un contador total configurado, el panel deriva de él el día, el mes y el año a través de Recorder, así que las cifras concuerdan entre sí. Las entidades escritas en los campos de periodo siguen guardadas pero no se usan: vacíalas, o quita el contador total si prefieres leer los periodos directamente.",
  "With bypass": "Con exclusiones",
  "With mains present the tile shows the battery charge; when power drops it shows the minutes left and lights up. No field is required: with the NUT status alone the tile already knows whether there is power. If you have more than one, add them below: each gets its own scene on the UPS page.":
    "Con red presente la tarjeta muestra la carga de la batería; cuando se va la luz muestra los minutos que quedan y se enciende. Ningún campo es obligatorio: con el estado de NUT la tarjeta ya sabe si hay tensión. Si tienes más de uno, añádelos abajo: cada uno tiene su escena en la página Alimentación de reserva.",
  "With the ground already wet the scheduled program skips (with the notice on the card); below the low threshold it starts on its own, once a day.":
    "Con el suelo ya mojado el programa previsto se omite (con el aviso en la tarjeta); por debajo del umbral bajo arranca solo, una vez al día.",
  "With this the page grows a switch: the state says whether it is working, this one commands it.":
    "Con esto la página gana un interruptor: el estado dice si trabaja, este la manda.",
  "Without PV": "Sin fotovoltaica",
  "Without a room this window has no humidity to watch: pick one above.":
    "Sin habitación esta ventana no tiene humedad que mirar: elige una arriba.",
  "Without an entity this row is nowhere to be seen: not on the Waste page, not on the Home tile. Pick one, or — if you have no calendar — write the two-week rota below, which needs no entity at all.":
    "Sin entidad esta fila no se ve en ningún sitio: ni en la página Residuos, ni en el mosaico de Inicio. Elige una o, si no tienes calendario, escribe abajo el turno de dos semanas, que no necesita ninguna entidad.",
  "Without the On/Off button": "Sin botón de encendido/apagado",
