  "evcc is not among the integrations with devices: the evcc integration for Home Assistant (HACS) is needed, with at least one loadpoint.":
    "No encuentro evcc entre las integraciones con dispositivos: hace falta la integración de evcc para Home Assistant (HACS), con al menos un loadpoint.",
  "evcc is the controller in front of the charger: it brings the charge mode, the charge limit you can command, the session and the solar share. Connect it alongside the charger, and neither takes the other's fields away.":
    "evcc es el regulador delante del cargador: de él llegan el modo de carga, el límite de carga que se puede mandar, la sesión y la cuota solar. Se conecta junto al cargador, y ninguno de los dos quita las casillas del otro.",
