  "Soil temperature": "Temperatura del suelo",
  "Take the ${quante} soil sensors Home Assistant found":
    "Coger los ${quante} sensores de suelo que Home Assistant ha encontrado",
  "The plants at home, one per row: the soil moisture sensor, the name, the drawing, and the temperature if there is one. The Plant care page says which need watering, which are waiting for rain and when the others will be due.":
    "Las plantas de casa, una por fila: el sensor de humedad del suelo, el nombre, el dibujo y, si la hay, la temperatura. La página Plantas dice cuáles hay que regar, cuáles esperan la lluvia y cuándo les tocará a las demás.",
  "The rain will see to it": "Ya se encarga la lluvia",
  "The sensor stuck in the soil, in percent: Ecowitt, Tuya, Xiaomi.":
    "El sensor clavado en la tierra, en porcentaje: Ecowitt, Tuya, Xiaomi.",
  "too wet": "demasiado húmeda",
  "Too wet above (%)": "Demasiado húmeda por encima de (%)",
  "Unnamed plant": "Planta sin nombre",
  "Until you pick the entity this plant is nowhere: not on the page, not on the Home tile.":
    "Mientras no elijas la entidad esta planta no está en ninguna parte: ni en la página, ni en la tarjeta de Inicio.",
  Waiting: "En espera",
  "watered just now": "regada hace un momento",
  "When the soil is dry but the home weather forecasts rain in the next hours, the plant waits instead of asking for water. Only for those the rain really reaches.":
    "Cuando la tierra está seca pero el tiempo de casa prevé lluvia en las próximas horas, la planta espera en lugar de pedir agua. Solo para las que la lluvia alcanza de verdad.",
  "${quante} readings out of range": "${quante} valores fuera de rango",
  "${ritardo} days late": "${ritardo} días de retraso",
  "After this many days the page and the Home tile say the water change is due.":
    "Pasados estos días, la página y la tarjeta de Inicio dicen que toca cambiar el agua.",
