  "TV menu": "Menú de la TV",
  "The TV's arrows, OK, back, home screen and channels, under its card and only while the TV is on. It needs the TV's remote.* entity: Samsung (Samsung Smart TV integration), Sony Bravia, Philips, Android TV and Google TV, Apple TV, Roku. LG webOS TVs don't need it.":
    "Las flechas, OK, atrás, la pantalla de inicio y los canales de la TV, bajo su tarjeta y solo con la TV encendida. Necesita la entidad remote.* de la TV: Samsung (integración Samsung Smart TV), Sony Bravia, Philips, Android TV y Google TV, Apple TV, Roku. Las LG webOS no la necesitan.",
  "These are in the house — one tap picks it:": "Estos están en casa — un toque lo elige:",
  "Volume down": "Bajar volumen",
  "Volume up": "Subir volumen",
  "${quante} actions": "${quante} acciones",
  "${quante} areas together: the buttons apply to all":
    "${quante} áreas juntas: los botones valen para todas",
  "Press and hold an area to pick more than one": "Mantén pulsada un área para elegir más de una",
  "1 action": "1 acción",
  "Close the ${nome} group": "Cerrar el grupo ${nome}",
  "Open the ${nome} group": "Abrir el grupo ${nome}",
  "The group is optional: actions with the same group sit together on Home, under a title that says how many are on and closes with a tap. Without groups it stays a single row.":
    "El grupo es opcional: las acciones con el mismo grupo van juntas en la Home, bajo un título que dice cuántas están encendidas y que se cierra con un toque. Sin grupos queda una sola fila.",
  "e.g. Lights, Shutters": "p. ej. Luces, Persianas",
  "💾 Group saved": "💾 Grupo guardado",
  "1 open · tap to close": "1 abierta · toca para cerrar",
  "open · tap to close": "abiertas · toca para cerrar",
  "1 open now · closed by hand": "1 abierta ahora · se cierra a mano",
  "open now · closed by hand": "abiertas ahora · se cierran a mano",
