  "locks unlocked": "cerraduras desbloqueadas",
  "shutter open": "persiana abierta",
  "shutters open": "persianas abiertas",
  "Under the weather, open doors and open windows are two pills. By default the class Home Assistant gives the contact decides; pick here when it is not the right one.":
    "Bajo el tiempo, las puertas abiertas y las ventanas abiertas son dos píldoras. Por defecto decide la clase que Home Assistant da al contacto; elige aquí cuando no es la correcta.",
  "If the camera already has its own integration in Home Assistant — Reolink, Tapo, Hikvision — the entity is already there: pick it in the field above, and the video goes through it.":
    "Si la cámara ya tiene su propia integración en Home Assistant — Reolink, Tapo, Hikvision —, la entidad ya existe: elígela en el campo de arriba y el vídeo pasa por ella.",
  "The stream name only works with the dashboard opened outside Home Assistant: in here it cannot be reached, and the camera goes through its entity.":
    "El nombre del stream solo vale con el panel abierto fuera de Home Assistant: aquí dentro no se alcanza, y la cámara pasa por su entidad.",
  "HLS: skipped, Home Assistant declares no stream for this camera":
    "HLS: omitido, Home Assistant no declara ningún flujo para esta cámara",
  "WebRTC: the go2rtc stream name only works with the dashboard opened outside Home Assistant — in here the camera goes through its entity":
    "WebRTC: el nombre del stream go2rtc solo vale con el panel abierto fuera de Home Assistant — aquí dentro la cámara pasa por su entidad",
  "WebRTC: tried first with its full time, the video did not arrive":
    "WebRTC: probado primero con todo su tiempo, el vídeo no llegó",
  Bypass: "Anular",
  "Bypass from the alarm?": "¿Anular en la alarma?",
