  "Add pack": "Añadir paquete",
  "An entity, or the number printed on the pack label with its unit. With every pack's capacity the overall charge is weighted by energy, and the page says when it will be full or empty.":
    "Una entidad, o el número impreso en la etiqueta del paquete con su unidad. Con la capacidad de cada paquete la carga total se pondera por energía, y la página dice cuándo estará lleno o vacío.",
  "average ${media}": "media ${media}",
  "Battery storage": "Almacenamiento en baterías",
  "BMS type": "Tipo de BMS",
