  "Cell ${cella.numero} · ${cifre(cella.volt, 3)} V":
    "Celda ${cella.numero} · ${cifre(cella.volt, 3)} V",
  "Cell ${cella.numero} · not answering": "Celda ${cella.numero} · no responde",
  "Cell imbalance": "Desequilibrio entre celdas",
