  health: "salud",
  "ideal below ${soglia}": "ideal por debajo de ${soglia}",
  "In Ah, Wh or kWh. Left empty, it is worked out from the charge and the capacity.":
    "En Ah, Wh o kWh. Si se deja vacía, se calcula a partir de la carga y la capacidad.",
  "It recognises JK, JBD and Daly BMS and Huawei LUNA2000 batteries from their entity names and groups them by prefix. It puts them here as rows, once: from then on they are yours.":
    "Reconoce los BMS JK, JBD y Daly y las baterías Huawei LUNA2000 por los nombres de sus entidades y los agrupa por prefijo. Los pone aquí como filas, una sola vez: a partir de ahí son tuyos.",
  "Optional. A battery that talks through the inverter — like the Huawei LUNA2000 with the Huawei Solar integration — has no BMS to choose: state of charge, power and energy go in Energy, “Flows & entities” tab, in the “Battery · charge” and “Battery · discharge” boxes. This tab is only for seeing the packs, or the modules, one by one.":
    "Opcional. Una batería que se comunica a través del inversor —como la Huawei LUNA2000 con la integración Huawei Solar— no tiene un BMS que elegir: el estado de carga, la potencia y la energía van en Energía, pestaña «Flujos y entidades», en los recuadros «Battery · charge» y «Battery · discharge». Esta pestaña solo sirve para ver los paquetes, o los módulos, uno por uno.",
  "max ${cifre(pacco.massima.volt, 3)} V · cell ${pacco.massima.numero}":
    "máx ${cifre(pacco.massima.volt, 3)} V · celda ${pacco.massima.numero}",
  "min ${cifre(pacco.minima.volt, 3)} V · cell ${pacco.minima.numero}":
    "mín ${cifre(pacco.minima.volt, 3)} V · celda ${pacco.minima.numero}",
  "MOS temperature": "Temperatura MOS",
  "needs balancing": "por equilibrar",
  "Needs balancing": "Por equilibrar",
  "Needs balancing above (mV)": "Por equilibrar por encima de (mV)",
  "New pack": "Paquete nuevo",
  "No battery pack": "Ningún paquete de baterías",
  "No battery pack configured": "Ningún paquete de baterías configurado",
  "No cells found": "No se encontraron celdas",
  "No pack answering": "Ningún paquete responde",
  "No reading": "Sin lectura",
  "One cell voltage per line, in cell order. You can paste them all at once, commas work too; “Find the cells” takes them from Home Assistant using the prefix of the pack's other entities.":
    "Una tensión de celda por línea, en el orden de las celdas. Puedes pegarlas todas a la vez, también separadas por comas; «Buscar las celdas» las toma de Home Assistant con el prefijo de las demás entidades del paquete.",
  "Optional: if the BMS does not publish it, the imbalance is worked out from the cells.":
    "Opcional: si el BMS no lo publica, el desequilibrio se calcula a partir de las celdas.",
  "Other BMS": "Otro BMS",
  "Pack 1": "Paquete 1",
  "Pack saved": "Paquete guardado",
  "Current sign": "Signo de la corriente",
  "Positive when charging (JK, JBD, Daly)": "Positiva al cargar (JK, JBD, Daly)",
  "Negative when charging": "Negativa al cargar",
  "With the sign the BMS uses: if it writes it negative while charging, pick that in “Current sign”.":
    "Con el signo que usa el BMS: si la escribe negativa al cargar, elígelo en «Signo de la corriente».",
  "If the page says “Discharging” while the battery is charging, your BMS writes the current the other way round: pick “Negative when charging”.":
    "Si la página dice «Descargando» mientras la batería se carga, tu BMS escribe la corriente al revés: elige «Negativa al cargar».",
  "Remaining energy": "Energía restante",
  "Save pack": "Guardar paquete",
  "State of charge (SoC)": "Estado de carga (SoC)",
  "State of health (SoH)": "Estado de salud (SoH)",
  "Take the ${quanti} packs Home Assistant found":
    "Tomar los ${quanti} paquetes que encontró Home Assistant",
  "The pack's charge percentage: without it the pack does not show.":
    "El porcentaje de carga del paquete: sin él el paquete no se muestra.",
  "The storage packs and their BMS: they show in the Batteries tab of Energy and on the Battery storage tile in Home. One pack per row: its entity is the state of charge, and inside are the others — health, voltages, currents, temperatures, cycles, capacity and every single cell.":
    "Los paquetes del almacenamiento y sus BMS: aparecen en la pestaña Baterías de Energía y en la tarjeta Almacenamiento en baterías de Inicio. Un paquete por fila: su entidad es el estado de carga, y dentro están las demás — salud, tensiones, corrientes, temperaturas, ciclos, capacidad y cada una de las celdas.",
  "to the house": "hacia la casa",
  "Unit of a hand-written capacity": "Unidad de una capacidad escrita a mano",
  "Unnamed pack": "Paquete sin nombre",
  "Until you pick the state of charge this pack is nowhere: not in Energy, not on the Home tile.":
    "Hasta que elijas el estado de carga este paquete no aparece en ningún sitio: ni en Energía ni en la tarjeta de Inicio.",
  "When the highest and lowest cells are further apart than this, the pack says “Needs balancing” and the Home tile asks for attention.":
    "Cuando la celda más alta y la más baja están más separadas que esto, el paquete dice «Por equilibrar» y la tarjeta de Inicio pide atención.",
  "${accese} of ${totale} lights on": "${accese} de ${totale} luces encendidas",
  "${lettura.posizione}% open": "${lettura.posizione}% abierta",
  "1 of ${totale} lights on": "1 de ${totale} luces encendida",
  "Everything with its own control, in a grid":
    "Cada cosa con su propio control, en una cuadrícula",
