  Remaining: "Restante",
  Resume: "Reanudar",
  "Seconds, minutes or hh:mm. Empty: uses the “Program duration”.":
    "Segundos, minutos o hh:mm. Vacío: usa la «Duración del programa».",
  "Seconds, minutes, hh:mm or the end time. Empty: uses the “Remaining time”.":
    "Segundos, minutos, hh:mm o la hora de fin. Vacío: usa el «Tiempo restante».",
  "started at ${partita}": "iniciado a las ${partita}",
  "The controls show up when cooking starts": "Los controles aparecen cuando empieza una cocción",
  "The entity_id given to services that do not name one. Empty: the cooking status.":
    "El entity_id que se da a los servicios que no indican uno. Vacío: el estado de la cocción.",
  "The rest of the kitchen": "El resto de la cocina",
  "The temperature sensor.": "El sensor de temperatura.",
  "The timer is stopped until it resumes": "El temporizador está parado hasta que se reanude",
  "Time and temperature set: it only needs starting":
    "Tiempo y temperatura elegidos: solo falta ponerlo en marcha",
  "Total time": "Tiempo total",
  "under a minute": "menos de un minuto",
  "What the “Cooking” entry of Appliances reads and presses. A control is an entity (button, switch, number, script) or a service with its parameters: philips_airfryer.adjust_time time=60 method=add. A button only shows up when its field is filled in, and only if it answers.":
    "Lo que la entrada «Cocción» de Electrodomésticos lee y pulsa. Un control es una entidad (button, switch, number, script) o un servicio con sus parámetros: philips_airfryer.adjust_time time=60 method=add. Un botón solo aparece si su campo está relleno, y solo si responde.",
  "Storage battery": "Batería de almacenamiento",
  "💾 Stove saved": "💾 Estufa guardada",
  "A fan, a number or a select. Without it, the thermostat's fan modes are used, if it has any.":
    "Un fan, un number o un select. Sin él se usan los modos de ventilador del termostato, si los tiene.",
  "A gas, pellet or wood boiler: flow, return, pressure, combustion.":
    "Una caldera de gas, de pélet o de leña: impulsión, retorno, presión, combustión.",
  "A number or a select, 1 to 5 or P1 to P5: on the page it becomes the dots with minus and plus.":
    "Un number o un select, de 1 a 5 o de P1 a P5: en la página se convierte en los puntos con el menos y el más.",
  "A pellet stove in a room: the flame, the power, the fan and the hopper. More than one, too.":
    "Una estufa de pellets en una estancia: la llama, la potencia, el ventilador y el depósito. También más de una.",
  "A sensor with the alarm text or a binary_sensor: when it trips, the page shows the red banner with its words.":
    "Un sensor con el texto de la alarma o un binary_sensor: cuando salta, la página muestra la franja roja con sus palabras.",
  "Add stove": "Añadir estufa",
  "An electric water heater, fed by the PV plant or not.":
    "Un termo eléctrico, alimentado o no por la instalación fotovoltaica.",
  "As a percentage or in kg, like the boiler's; or a binary_sensor that turns on when the pellet is running low.":
    "En porcentaje o en kg, como el de la caldera; o un binary_sensor que se enciende cuando el pélet se está acabando.",
  "Brazier cleaning": "Limpieza del brasero",
  "Check the stove's display.": "Mira la pantalla de la estufa.",
  "Flame · Power · Pellet": "Llama · Potencia · Pélet",
  "For whoever has two hoppers: the page shows them side by side, Pellet 1 and Pellet 2, with the same threshold as the first.":
    "Para quien tiene dos depósitos: la página los muestra uno al lado del otro, Pélet 1 y Pélet 2, con el mismo umbral que el primero.",
  Ignition: "Encendido",
  "In alarm": "En alarma",
  "Living room stove": "Estufa del salón",
  "Lower the power": "Bajar la potencia",
  Modulating: "Modulación",
  "No stove configured": "Ninguna estufa configurada",
  "On its own it covers nearly everything: on and off, the target, the room temperature and, if it has them, the fan modes.":
    "Él solo cubre casi todo: encendido y apagado, el objetivo, la temperatura de la estancia y, si los tiene, los modos del ventilador.",
  "Pellet level, second hopper": "Nivel de pélet, segundo depósito",
  "Pellet OK": "Pélet suficiente",
  "Pellet running low": "Pélet a punto de acabarse",
  "Power level": "Nivel de potencia",
  "Raise the power": "Subir la potencia",
  "Roof collectors and a tank: the fields are the ones below.":
    "Captadores en el tejado y un acumulador: los campos son los de abajo.",
  "Room temperature": "Temperatura de la estancia",
  "Save stove": "Guardar estufa",
  "Shutting down": "Apagando",
  "Slow the fan down": "Bajar el ventilador",
  "Speed the fan up": "Subir el ventilador",
  Stove: "Estufa",
  "Stove alarm": "Alarma de la estufa",
  "Stove controls": "Mandos de la estufa",
  "Stove phase": "Fase de la estufa",
  "Stove thermostat": "Termostato de la estufa",
  "Switch (when there is no thermostat)": "Interruptor (si no hay termostato)",
  "The stove heats the room it stands in: the page draws the flame, the power, the fan, the flue and the hopper, and gives you the buttons for on and off, the target, the power and the fan. No field is required: with just the thermostat the page already has almost everything. With more than one, add them here and the page grows a row to switch between them.":
    "La estufa calienta la estancia en la que está: la página dibuja la llama, la potencia, el ventilador, el tubo de humos y el depósito, y te da los botones para encender y apagar, el objetivo, la potencia y el ventilador. Ningún campo es obligatorio: solo con el termostato la página ya lo tiene casi todo. Si tienes más de una, añádelas aquí y en la página aparece una fila para cambiar de una a otra.",
  "The word the stove shows on its display: ignition, working, brazier cleaning, shutdown… If the page does not know it, it shows it as it is.":
    "La palabra que la estufa muestra en su pantalla: encendido, trabajo, limpieza del brasero, apagado… Si la página no la conoce, la muestra tal cual.",
  "Without it, the thermostat's own reading is used.":
    "Sin él, se usa la lectura del propio termostato.",
  Working: "Trabajo",
  "Air conditioners out of season": "Aires acondicionados fuera de temporada",
  "Radiators out of season": "Radiadores fuera de temporada",
  "They show: ${periodo}. Switched on, they show anyway.":
    "Se ven: ${periodo}. Encendidos, aparecen igualmente.",
  "Show them anyway": "Mostrarlos igualmente",
  "🐠 The aquarium's entities": "🐠 Las entidades del acuario",
  "🦎 The terrarium's entities": "🦎 Las entidades del terrario",
  "🧽 Cleaning": "🧽 Limpieza",
  "🪣 The tank": "🪣 El tanque",
  Aquariums: "Acuarios",
  "Aquariums and terrariums": "Acuarios y terrarios",
  "Bowl · Litter · Aquariums · Terrariums": "Comedero · Arenero · Acuarios · Terrarios",
  Cats: "Gatos",
  "Clean every (days)": "Limpiar cada (días)",
