  Dogs: "Perros",
  "Heat lamp or heating": "Lámpara de calor o calefacción",
  "Humidity too high": "Humedad demasiado alta",
  "Humidity too low": "Humedad demasiado baja",
  "Last cleaning": "Última limpieza",
  Mister: "Nebulizador",
  "Not recorded yet: tap “Done today” on the day you clean it, and from then on the card counts the days.":
    "Aún no está anotado: toca «Hecho hoy» el día que lo limpies, y desde entonces la tarjeta cuenta los días.",
  "One row per entity: temperature and pH with their ideal range, the water level, the lights, the filter and the heater. Empty ranges use the defaults: 24–27 °C and pH 6.5–7.5.":
    "Una fila por entidad: la temperatura y el pH con su rango ideal, el nivel del agua, las luces, el filtro y el calentador. Los rangos vacíos usan los valores por defecto: 24–27 °C y pH 6,5–7,5.",
  "One row per entity: warm-side and cool-side temperatures, humidity, lights, heat lamp, UVB, mister. Empty ranges use the defaults: 28–35 °C on the warm side, 22–28 °C on the cool side, humidity 40–80 %.":
    "Una fila por entidad: temperaturas de la zona cálida y de la zona fresca, humedad, luces, lámpara de calor, UVB, nebulizador. Los rangos vacíos usan los valores por defecto: 28–35 °C en la zona cálida, 22–28 °C en la fresca, humedad 40–80 %.",
  "Optional: left empty, the terrarium reminds nobody to clean it. With a number the card says when it is due.":
    "Opcional: si se deja vacío, el terrario no recuerda a nadie que hay que limpiarlo. Con un número la tarjeta dice cuándo toca.",
  "Other pet": "Otro animal",
  "Other pets": "Otros animales",
  "Other reading": "Otra medida",
  "Reservoir level": "Nivel del depósito",
  "Take the ${quante} terrarium entities Home Assistant found":
    "Coger las ${quante} entidades del terrario que Home Assistant ha encontrado",
  "Temperature (cool side)": "Temperatura (zona fresca)",
  "Temperature (warm side)": "Temperatura (zona cálida)",
