  "Terrarium climate": "Clima del terrario",
  Terrariums: "Terrarios",
  "The pets of the house: one card each, with its photo and what concerns it — the bowl, the litter box, the water, the microchip door, the collar. Aquariums and terrariums too, as many as you have: each with its own entities.":
    "Las mascotas de la casa: una tarjeta para cada una, con su foto y lo que le concierne: el comedero, el arenero, el agua, la gatera con microchip, el collar. También acuarios y terrarios, todos los que tengas: cada uno con sus entidades.",
