  "Heating · Cooling": "Calor · Frío",
  "It fills itself with the source dashboard's climate, split into the Cooling and Heating tabs like the Climate section: air conditioners in cooling, radiators and thermostats in heating, heat pumps in both.":
    "Se llena sola con la climatización del panel de origen, dividida en las pestañas Frío y Calor como en la sección Clima: aires acondicionados en frío, radiadores y termostatos en calor, bombas de calor en ambas.",
  "Opens on": "Se abre en",
