  "Shown on the tab at the top": "Se muestra en la pestaña de arriba",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "El panel de la tableta de pared. Elige las páginas —las pestañas de arriba— y qué contiene cada una. En la tableta, manteniendo pulsado el reloj dos segundos vuelves aquí.",
