  "The player that's playing, big, with cover, buttons, volume and sources; beside it the others, each with its own play. A tap on a player brings it up big.":
    "El reproductor que suena, en grande, con carátula, botones, volumen y fuentes; al lado los demás, cada uno con su play. Un toque en un reproductor lo pone en grande.",
