  "Someone at the door": "Llaman a la puerta",
  "When an alert turns on or the alarm goes off, the panel wakes up and shows it big until someone taps “Got it”":
    "Cuando se activa un aviso o salta la alarma, el panel se despierta y lo muestra en grande hasta que alguien toca «Visto»",
