  "The pages in a column of big buttons on the left, like on control-room panels. Landscape only: in portrait and on small screens the tabs at the top stay":
    "Las páginas en una columna de botones grandes a la izquierda, como en los paneles de control. Solo en horizontal: en vertical y en pantallas pequeñas se quedan las pestañas arriba",
