  Command: "Comando",
  "▲ command": "Comando ▲",
  "▼ command": "Comando ▼",
  "Start command": "Comando de inicio",
  "Mute command": "Comando de silencio",
  "Stop command": "Comando de parada",
  "The dashboard doesn't know the arrows of ${nome}: the remote shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "El panel no conoce las flechas de ${nome}: el mando aparece entre los comandos como botón de encendido/apagado. Sus comandos se añaden en «Otros comandos», como remote.name:command.",
  "Home Assistant doesn't say which integration this remote belongs to: it shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "Home Assistant no dice de qué integración es este mando: aparece entre los comandos como botón de encendido/apagado. Sus comandos se añaden en «Otros comandos», como remote.name:command.",
  "Device (optional)": "Dispositivo (opcional)",
  "Remote device": "Dispositivo del mando",
  "Optional: the «device» of remote.send_command": "Opcional: el «device» de remote.send_command",
  "The live picture on the left, arrows and zoom on the right, presets below. Each button presses an entity already in Home Assistant: a camera button, a script with onvif.ptz, or a remote with the command to send. A button without an entity stays off.":
    "La imagen en directo a la izquierda, las flechas y el zoom a la derecha, los presets debajo. Cada botón pulsa una entidad que ya existe en Home Assistant: un botón de la cámara, un script con onvif.ptz o un mando (remote) con el comando que enviar. Un botón sin entidad queda apagado.",
  "Read level (optional)": "Nivel leído (opcional)",
  "Each channel is an upright fader with its mute: a player's volume, or a number (number, input_number) like a mixer's dB. A sensor becomes a meter you look at; a remote gets ▲ / ▼ and mute, each with its own command (remote.send_command). Mute is the player's own, a switch (on means muted), a remote or a button to press.":
    "Cada canal es un fader vertical con su silencio: el volumen de un reproductor, o un número (number, input_number) como los dB de un mezclador. Un sensor se convierte en un medidor que se mira; un mando (remote) tiene ▲ / ▼ y silencio, cada uno con su comando (remote.send_command). El silencio es el del reproductor, un interruptor (encendido significa silenciado), un mando o un botón que pulsar.",
  "What the integration publishes next to the player — a TV's power switch, the input dropdown, a scene: button.*, select.*, switch.* entities (plus input_*, script.*, scene.*). A remote.* turns on and off; written remote.name:command (for example remote.amp:volume_up) it sends that command. They appear on the card under the playback controls.":
    "Lo que la integración publica junto al reproductor — el interruptor de encendido de una TV, el desplegable de la fuente, una escena: entidades button.*, select.*, switch.* (y input_*, script.*, scene.*). Un mando remote.* se enciende y se apaga; escrito remote.name:command (por ejemplo remote.amp:volume_up) envía ese comando. Aparecen en la tarjeta bajo los controles de reproducción.",
  "Scale: to": "Escala: hasta",
  "Scale: from": "Escala: desde",
  "A button.*, select.*, switch.* or remote.* entity is required (also remote.name:command) — or input_button, input_select, input_boolean, script, scene.":
    "Se necesita una entidad button.*, select.*, switch.* o remote.* (también remote.name:command) — o input_button, input_select, input_boolean, script, scene.",
  "A sensor with the level": "Un sensor con el nivel",
  "Empty: turns on": "Vacío: enciende",
  "Empty: turns off": "Vacío: apaga",
  "${inserite} of ${tutte} armed": "${inserite} de ${tutte} armadas",
  "Add a command": "Añadir un comando",
  "Add a partition": "Añadir una partición",
  "Add a reading": "Añadir una lectura",
  "Alarm · ${quante} areas": "Alarma · ${quante} áreas",
  "Alarm partitions": "Particiones de la alarma",
  "Buttons next to the readings: locks (lock and unlock), scripts, buttons, scenes, switches, blinds. A remote turns on and off; written remote.name:command it sends that command.":
    "Botones junto a las lecturas: cerraduras (cierran y abren), scripts, botones, escenas, interruptores, persianas. Un mando (remote) se enciende y se apaga; escrito remote.name:command envía ese comando.",
  "Empty: all the ones from the dashboard's Security section":
    "Vacío: todas las de la sección Seguridad del panel",
  "Intercom / camera": "Interfono / cámara",
  "Leaving and who is home": "Salida y quién está en casa",
  "All clear": "Todo bien",
  "Open doors": "Puertas abiertas",
  "Open doors and windows": "Puertas y ventanas abiertas",
  "since ${ora}": "desde las ${ora}",
  "The entries declared in the Security section": "Los accesos declarados en la sección Seguridad",
  "The ones chosen here, in this order: each with its state and its buttons, the ones its panel accepts":
    "Las elegidas aquí, en este orden: cada una con su estado y sus botones, los que acepta su central",
  "Under the alarm, each with its value: doors and windows (binary_sensor), sensors, locks, blinds. Two or more doors or windows become a single count, «Open windows: 2»; a tap lists them.":
    "Bajo la alarma, cada una con su valor: puertas y ventanas (binary_sensor), sensores, cerraduras, persianas. Dos o más puertas o ventanas se convierten en un solo recuento, «Ventanas abiertas: 2»; un toque las enumera.",
  "Water!": "¡Agua!",
  "Next to the people": "Junto a las personas",
  "No extra reading: the row says whether it is up or down, nothing else.":
    "Ninguna lectura más: la fila dice si está activo o caído, y nada más.",
  Nothing: "Nada",
  "The sensors that tell more about this device than “up” and “down” — ping latency, packet loss, uptime, the last time it was seen: sensor.*, binary_sensor.*, number.* entities. They show under its row on the MiniPC page, with their own name and unit.":
    "Los sensores que cuentan de este aparato algo más que «activo» y «caído» — la latencia del ping, los paquetes perdidos, el tiempo encendido, la última vez que se vio: entidades sensor.*, binary_sensor.*, number.*. Aparecen bajo su fila en la página MiniPC, con su nombre y su unidad.",
