  "the car": "el coche",
  "The house assistant watches the house for you and tells you the most important thing to do right now: lights left on in an empty house, a window open with the heating on, rain on its way, the laundry done, spare solar power. It learns from what you dismiss, and remembers it for the whole household. On a computer or tablet it sits to the right of the people, on a phone below them.":
    "El asistente de casa vigila la casa por ti y te dice lo más importante que hacer ahora: luces encendidas con la casa vacía, una ventana abierta con la calefacción puesta, lluvia en camino, la colada terminada, sol que sobra. Aprende de lo que descartas y lo recuerda para toda la casa. En el ordenador y la tableta está a la derecha de las personas; en el móvil, debajo.",
  "The house is drawing ${kw} kW from the grid": "La casa toma ${kw} kW de la red",
  "The house is empty and ${nomi(aperte, l)} is unlocked":
    "La casa está vacía y ${nomi(aperte, l)} no está cerrada con llave",
