  "You're near the meter's limit.": "Estás cerca del límite del contador.",
  "You're out and ${g.name} is open": "Estáis fuera y ${g.name} está abierto",
  "e.g. 30": "p. ej. 30",
  "End-of-cycle delay under ${minuti} minutes: 0 W pauses mid-programme look like the end of the cycle.":
    "Retardo de fin de ciclo por debajo de ${minuti} minutos: las pausas a 0 W a mitad de programa parecen el final del ciclo.",
  "Recommended: running ${a} W, standby ${b} W, delay ${minuti} min.":
    "Recomendado: en marcha ${a} W, standby ${b} W, retardo ${minuti} min.",
  "Running threshold under 1 W: a lit display is enough to show Running.":
    "Umbral de marcha por debajo de 1 W: basta la pantalla encendida para aparecer En marcha.",
  "Standby threshold at or above the running one: standby can never show.":
    "Umbral de standby igual o superior al de marcha: el standby nunca puede aparecer.",
  "Use the recommended values": "Usar los valores recomendados",
  "With these values one cycle can turn into many mini-cycles.":
    "Con estos valores un solo ciclo puede convertirse en muchos miniciclos.",
