  "This automation uses advanced features (a choice between cases, a template, a blueprint…): here you can turn it on and off, run it, rename it and change its room. For the rest:":
    "Esta automatización usa funciones avanzadas (una elección entre casos, una plantilla, un blueprint…): aquí puedes encenderla, apagarla, ejecutarla, renombrarla y cambiarle la habitación. Para lo demás:",
