  "Choose the weather entity in ⚙️ Config › On the wall › More settings › Weather, or add a weather integration in Home Assistant.":
    "Elige la entidad del tiempo en ⚙️ Config › En la pared › Más ajustes › Tiempo, o añade una integración meteorológica en Home Assistant.",
  "Choose the weather entity in More settings › Weather, or add a weather integration in Home Assistant":
    "Elige la entidad del tiempo en Más ajustes › Tiempo, o añade una integración meteorológica en Home Assistant",
  "Forecast on its way…": "Previsión en camino…",
  "Full-page weather: what it's like now, big, with feels-like, humidity, wind and pressure, then the coming hours and days. It uses the same weather the tablet shows at the top and on the rest screen.":
    "El tiempo a página completa: cómo está ahora, en grande, con sensación térmica, humedad, viento y presión, luego las próximas horas y días. Usa el mismo tiempo que la tableta muestra arriba y en la pantalla de reposo.",
  gusts: "ráfagas",
  "Hour by hour": "Hora a hora",
